+/// The last [`accumulator_pi_len`] entries of an inner proof's instance. 
+fn accumulator_tail<T>(instance: &[T]) -> anyhow::Result<&[T]> {
+    let acc_len = accumulator_pi_len();
+    instance
+        .len()
+        .checked_sub(acc_len)
+        .map(|start| &instance[start..])
+        .ok_or_else(|| {
