+/// Constructs the accumulator from the instance.
+fn carried_accumulator(instance: &[outer::Scalar]) -> anyhow::Result<Accumulator<S>> {
+    let tail = accumulator_tail(instance)?;
+    let acc = reconstruct_accumulator(tail).ok_or_else(|| {
+        anyhow!(
